insert into public.protocol_templates (id,code,title,purpose,trigger_text,document_id,owner_role,category,status,template_rev,kind,sop_ref,process_owner,policy_refs,indicator_ids) values
('55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,'PR-DUTY-HANDOVER','Duty shift handover','Keep 24/7 operations continuous between shifts.','Every change of duty shift at the Operations Center.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'duty_officer'::public.app_role,'daily_operations','draft',1,'protocol','MOO Ch.2 Annex 2-E (HR-F04)','CDRRMO Operations and Warning Division (duty officer on shift)',array['RA 10121 Sec. 12(c)','NDRRMC Memo 131 s. 2018']::text[],array['A2.5','B4.3']::text[]),
('f726b603-075b-5232-a798-5054f4d3e64d'::uuid,'PR-WARNING-DISSEM','Warning dissemination','Move a hazard bulletin to every at-risk purok, in a form people understand.','On receipt of a PAGASA, PHIVOLCS or MGB bulletin or advisory that affects Ormoc.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'duty_officer'::public.app_role,'warning','draft',1,'protocol','EOC Manual Ch.2 (warning)','CDRRMO Operations and Warning Division',array['RA 10121 Sec. 12(c)','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['A6.1','A6.2','A6.3','A6.4','B5.6']::text[]),
('fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,'PR-EOC-ACTIVATE','EOC activation (Blue or Red)','Stand up the EOC quickly with the right people and records.','When the EOC is raised to Blue or Red as directed by the City Mayor (Responsible Official), or by the EOC Manager under the approved activation protocol.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','EOC Manual Ch.2 (activation)','EOC Manager',array['NDRRMC Memo 131 s. 2018','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['B1.2','B1.3','B4.1','B4.2']::text[]),
('c79bca15-67f0-538e-9e52-8d969da30076'::uuid,'PR-PDRA','Pre-disaster risk assessment (PDRA)','Decide, from the forecast and local exposure, whether to monitor, act early or request a declaration.','When a forecast hazard may affect Ormoc.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','EOC Manual Ch.2 (PDRA)','EOC Manager with the PDRA core group',array['RA 12287 and its IRR (2026)']::text[],array['A8.6','A8.8']::text[]),
('5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,'PR-SOID-REQUEST','State of Imminent Disaster: request and declaration','Follow RA 12287, its IRR and SOP GOV-05 from the PDRA to the Mayor''s Executive Order.','When the PDRA classifies the projected impact as severe or its equivalent (including where IRR Rule II Sec. 4 factors support that classification below the thresholds) and there is enough lead time to carry out anticipatory action.','f66e432b-487f-5434-a8eb-de42ef848a67'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP GOV-05 (Annex 1-F)','CDRRMO Head as CDRRMC secretariat',array['RA 12287 and its IRR (2026), Rules III and IV']::text[],array['A1.8','A4.6','A6.7']::text[]),
('f99e18a5-6514-56f9-8bf6-dc31df80cd6f'::uuid,'PR-SOC-DECLARE','State of Calamity: assessment, declaration and lifting','Follow RA 10121 Sec. 16 and SOP GOV-04: the Sangguniang Panlungsod declares or lifts, on the CDRRMC''s recommendation.','When damage and needs reports indicate that a State of Calamity may be warranted.','e715b34c-ec5f-5f4c-b34c-378225a2156c'::uuid,'cdrrmo_head'::public.app_role,'council','draft',1,'workflow','SOP GOV-04 (Annex 1-E)','CDRRMO Head as CDRRMC secretariat',array['RA 10121 Sec. 16']::text[],array['A1.6']::text[]),
('7bcbdc7d-00f9-516a-a030-e4d89022be09'::uuid,'PR-FLASHFLOOD-EARLY','Flash flood and landslide early action','Act on short-lead hazards that cannot wait for a declaration.','When rainfall or river readings reach the City''s early-action thresholds for the Anilao–Malbasag system or upland barangays.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'duty_officer'::public.app_role,'anticipatory_action','draft',1,'protocol','EOC Manual Ch.2 (short-lead hazards)','CDRRMO Operations and Warning Division',array['RA 10121 Sec. 12(c)','RA 12287 IRR (2026) Rule IV']::text[],array['A6.1','A6.2','A8.8']::text[]),
('90cb1850-de66-5a00-a46c-47db38ebdc84'::uuid,'PR-SITREP-CYCLE','SitRep cycle','Produce a verified SitRep on schedule every operational period.','At each scheduled SitRep time during an activation.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'eoc_staff'::public.app_role,'reporting','draft',1,'protocol','EOC Manual Ch.6 (reporting)','EOC Planning Section',array['DILG VIII Harmonized Disaster Response Reporting Template and SOP','NDRRMC Memo 131 s. 2018']::text[],array['B5.1','B5.2','A10.3']::text[]),
('a37bb249-1b6f-585a-8b12-bc80b742cc63'::uuid,'PR-CDRRMC-MEETING','CDRRMC meeting (secretariat)','Run the Council meeting and keep its records complete.','Quarterly, and whenever the Chair calls a special meeting.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'duty_officer'::public.app_role,'council','draft',1,'workflow','MOO Ch.1 (CDRRMC secretariat)','CDRRMO as CDRRMC secretariat',array['RA 10121 Sec. 11']::text[],array['A1.3','A1.4']::text[]),
('33dfaee2-77a8-5b13-956e-bb805634d0b1'::uuid,'PR-LIFT-REPORT','Lifting and 45-day report','Lift a State of Imminent Disaster correctly and report to OCD on time.','When the hazard occurs or the PDRA shows the projected impacts will not be met.','24c36b6b-9a56-5f61-acb4-8a529b7fc33c'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','MOO Ch.7 (lifting and reporting)','CDRRMO Head',array['RA 12287 and its IRR (2026)']::text[],array['A10.8']::text[]),
('abcc88a5-8f0d-577d-84f7-eef04656abf0'::uuid,'WF-BUDGET-CYCLE','LDRRMF budget cycle (formulation to quarterly report)','Research and Planning leads formulation, Administration leads execution, the Head approves and the CDRRMC endorses (Ch.2 sec. 2.16.2).','Each budget call, and every quarter for the results-and-finance report.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','MOO Ch.2 sec. 2.16.2','CDRRMO Research and Planning (formulation); Administration and Training (execution)',array['RA 10121 Sec. 21','NDRRMC-DBM-DILG JMC 2013-1']::text[],array['A3.5','A4.1','A4.2','A4.4']::text[]),
('bf7c56c0-7c61-596a-bab4-0136aa67927d'::uuid,'WF-CP-ACTIVATION','Contingency plan activation and response clustering','Switch on the clusters and EOC modules the activated contingency plan needs, and stand them down when needs are met (Ch.1 sec. 6.3).','When the EOC goes to Blue or Red for a hazard covered by a contingency plan.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'eoc_manager'::public.app_role,'response_clusters','draft',1,'workflow','MOO Ch.1 sec. 6.3','EOC Manager',array['NDRRMC Memo 131 s. 2018']::text[],array['A8.5','B1.4','B4.4']::text[]),
('41fad6bf-c424-5923-b011-9067cf54de64'::uuid,'WF-EOC-DESIGNATION','EOC designation review (quarterly)','Keep every key EOC position covered by a primary and two alternates (Annex 2-D; IAT B4.2).','Every quarter, and after any staff movement.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'cdrrmo_head'::public.app_role,'workforce','draft',1,'workflow','MOO Ch.2 Annex 2-D','CDRRMO Head',array['NDRRMC Memo 131 s. 2018','EOC Capability Assessment Checklist']::text[],array['B4.1','B4.2']::text[]),
('a277ed09-4908-5ad8-a47d-9d583ee2137d'::uuid,'WF-GEO-COP','Geospatial common operating picture (SOP 6-GIS-01)','Keep a consistent, validated map of incidents, affected areas, facilities and resources for the EOC.','Maintained in normal operations; run in full whenever the EOC is activated.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'eoc_staff'::public.app_role,'geospatial','draft',1,'workflow','SOP 6-GIS-01 (EOC Manual Ch.6)','EOC Planning Section (GIS custodian)',array['NDRRMC Memo 131 s. 2018','RA 10173']::text[],array['A5.6','A5.7','B5.3']::text[]),
('4e10fa52-dda1-5ce8-b699-974ea48663df'::uuid,'WF-SOP3-01','SOP 3-1 Hazard data acquisition, validation and map release','Obtain authoritative, current and fit-for-purpose hazard information and control its use.','A request for risk information or a map; a new or revised product from a source agency.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-1 (MOO Ch.3 v1.0)','CDRRMO Research and Planning (GIS custodian)',array['RA 10121 Sec. 12(c)(3)','DHSUD MC 2025-004']::text[],array['A5.1','A5.6','C1.4']::text[]),
('49df9ce9-eaa5-5907-b3fa-a06882687788'::uuid,'WF-SOP3-02','SOP 3-2 Risk information and geospatial repository maintenance','Maintain a controlled, auditable City risk information base.','A new dataset; quarterly review; after a major event or a source-agency revision.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-2 (MOO Ch.3 v1.0)','CDRRMO Head (designated data custodian)',array['RA 10121 Sec. 12(c)(3) and (5)','RA 10173']::text[],array['A5.4','A5.5','A5.6','A5.7']::text[]),
('c624dc19-e6b9-51fe-bef6-d0ef90298714'::uuid,'WF-SOP3-03','SOP 3-3 City climate and disaster risk assessment','Produce a method-compliant CDRA that supports CLUP and development decisions.','CDRA update with the CLUP/CDP revision; material change in hazard, exposure or climate information; new DHSUD issuance.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-3 (MOO Ch.3 v1.0)','CPDO (CDRA process) with the CDRRMO coordinating DRRM evidence',array['DHSUD MC 2025-004 (Enhanced CDRA)','RA 9729 as amended by RA 10174','RA 10121 Sec. 12(c)(3)']::text[],array['A5.2','A5.3','C1.1','C1.3']::text[]),
('90158e48-f867-57e2-a9da-980f5d20e634'::uuid,'WF-SOP3-04','SOP 3-4 Critical facilities and dependency/failure-chain analysis','Identify critical service dependencies and inform protection and restoration priorities.','Yearly; after a change to a critical asset; before a contingency plan or PSCP update.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-4 (MOO Ch.3 v1.0)','CDRRMO (coordination); asset owners accountable for asset data',array['RA 12287 IRR (2026) Rule I Sec. 5(b),(d)']::text[],array['A5.8']::text[]),
('c4aa5d23-496f-53b2-9a86-60a56971a06d'::uuid,'WF-SOP3-05','SOP 3-5 LDRRMP and DRR/CCA mainstreaming interface','Ensure risk evidence is converted into plans, programmes and budget decisions.','Yearly planning and budget cycle (AIP, LDRRMFIP); LDRRMP review; each investment proposal.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-5 (MOO Ch.3 v1.0)','CDRRMO (LDRRMP); CPDO (development-plan integration)',array['RA 10121 Sec. 2 and 12(c)(6)','RA 7160','RA 9729 as amended by RA 10174','NDRRMC-DBM-DILG JMC 2013-1']::text[],array['A3.1','A3.2','C1.1','C1.2','C1.4']::text[]),
('bf9ab417-2698-5c21-9201-36856ff49f99'::uuid,'WF-SOP3-06','SOP 3-6 Hazard-specific contingency plan development and control','Prepare and maintain tested plans for priority hazard scenarios.','A priority hazard without a current plan; a plan past its validity; after an exercise or event; yearly review.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'contingency_planning','draft',1,'workflow','SOP 3-6 (MOO Ch.3 v1.0)','CDRRMO (coordinating process owner); hazard and sector leads (technical owners)',array['RA 10121 Sec. 12(c)','OCD/NDRRMC contingency-planning manual (current edition to be obtained)']::text[],array['A3.3','A3.6']::text[]),
('7ff2c261-e05f-5d3a-9699-ff0b584a84c1'::uuid,'WF-SOP3-07','SOP 3-7 Public service continuity planning','Protect essential City functions during disruption.','Mayor''s directive; yearly review; after a disruption or exercise.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'continuity','draft',1,'workflow','SOP 3-7 (MOO Ch.3 v1.0)','City continuity executive (to be designated); department heads for their services',array['NDRRMC-OCD PSCP Guidebook']::text[],array['A3.4','B2.7']::text[]),
('3d22ea60-9da2-50c2-889c-f70876393abf'::uuid,'WF-SOP3-08','SOP 3-8 Barangay DRRM plan review and quality assurance','Maintain a verified, quality-assured city-wide BDRRMP status for the 85 barangays.','Yearly BDRRMP cycle; DILG call for plans; a new plan period.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-8 (MOO Ch.3 v1.0)','BDRRMC/Barangay Development Council (plan owner); CDRRMO (city reviewer)',array['RA 10121 Sec. 12(c)(6)','DILG MC 2025-035 (Listo si KAP)']::text[],array['A3.7']::text[]),
('df644c53-097f-508d-a224-5f5f3277a454'::uuid,'WF-SOP3-09','SOP 3-9 Inclusive risk assessment and ecosystem monitoring interface','Embed inclusion and protective-ecosystem evidence in risk intelligence and preparedness.','Each CDRA or plan update; yearly monitoring.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-9 (MOO Ch.3 v1.0)','CDRRMO (coordination); sector offices and CENRO/DENR (technical owners)',array['RA 9710','RA 7277 as amended','RA 10821','RA 8371','RA 10173','RA 9729 as amended by RA 10174']::text[],array['A5.3','A5.5','A7.6','C3.1','C3.2']::text[])
insert into public.protocol_steps (id,template_id,seq,instruction,is_critical,requires_note,due_offset_minutes,form_code) values
('7b4f30ce-80a5-50b8-8b3f-9b665f04d2e9'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,1,'Read the logbook entries since the last handover',false,false,0,'STEP-RECORD'),
('f76135e7-704d-5211-871a-18639ce440a5'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,2,'Review open incidents, resource requests and pending barangay reports',true,false,5,'STEP-RECORD'),
('de1d96cd-2acb-5d95-abc5-7a2f9845a9bc'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,3,'Check the latest PAGASA and PHIVOLCS bulletins and record any change',true,true,10,'STEP-RECORD'),
('20b4a938-cb8c-5acd-afa3-07c45e6deb79'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,4,'Run the radio net check with the barangays scheduled for this shift',true,true,20,'STEP-RECORD'),
('891f3462-6f4b-5649-aeb7-7a38fa30e2c8'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,5,'Check generator fuel, UPS and backup internet status',false,true,25,'STEP-RECORD'),
('d0c39b49-78f2-550e-a961-f96280cbfbc5'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,6,'Record handover notes and sign off with the incoming duty officer',true,true,30,'HR-F04'),
('76cbabd3-218b-5e4a-b8e5-6ace194a0978'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,1,'Log the bulletin: issuer, number, time issued, hazard and areas',true,true,0,'EOC-WARN-01'),
('e28ac733-4b98-54d8-a8f5-1e669cff5cd4'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,2,'Check it against the City warning-to-action matrix and note the matching alert and actions',true,true,10,'STEP-RECORD'),
('7e03ea6d-103e-5725-8cc8-0ea0143c0fb3'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,3,'Notify the EOC Manager and CDRRMO Head; record the instruction received',true,true,15,'STEP-RECORD'),
('971261f1-d074-511d-b15a-233304fce743'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,4,'Issue the advisory in Cebuano, with Filipino/English and accessible formats as needed',true,false,30,'STEP-RECORD'),
('e8e4c9bb-70ad-500b-a769-7b65168d381a'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,5,'Send through every channel: emergency cell broadcast/SMS, radio, social media, barangay officials',true,true,40,'STEP-RECORD'),
('40b627a7-0af1-5cf1-83e7-843c0c0c5bd3'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,6,'Confirm receipt from riverine, coastal and upland barangays first, then the rest',true,true,60,'EOC-WARN-02'),
('d5a35cb5-9820-53c5-946d-d65fb0a32b7f'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,7,'Log barangays that did not confirm and assign follow-up',false,true,75,'STEP-RECORD'),
('cd64827e-a96b-5fcd-bfb7-3ed7d5ecdc54'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,1,'Record the level change and reason in the platform (logs it automatically). If no device can connect, write it in the paper logbook with the time and enter it once connected',true,false,0,'EOC-ACT-01'),
('c84e068c-60c3-51af-925f-532b4dc62505'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,2,'Notify CDRRMC members, cluster leads and liaison desks of the activation',true,true,15,'STEP-RECORD'),
('95d5a158-d9b2-5721-936f-7119e10924f2'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,3,'Fill EOC positions from the roster, with alternates',true,true,30,'HR-F05'),
('d83ee728-0913-5aea-a8f9-368e3ba41809'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,4,'Run the communications check on all redundant channels',true,true,30,'STEP-RECORD'),
('6ff329f4-ff72-5d9a-a662-4161c775394b'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,5,'Set the operational period and the SitRep schedule',true,true,45,'STEP-RECORD'),
('14c130f6-09a6-51db-83aa-8d96fe5b15e2'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,6,'Brief the Mayor on the situation and decisions needed',true,true,60,'STEP-RECORD'),
('4f17821c-f260-5257-b5e2-8df477adf587'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,1,'Convene the PDRA core group and record attendance by office',true,false,0,'STEP-RECORD'),
('309ebaee-2082-5388-a60c-8800074ec960'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,2,'Review the forecast: hazard, expected impact time, areas, impact level',true,true,15,'STEP-RECORD'),
('384773c7-bacd-59eb-840e-b56a87ee9538'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,3,'Identify exposed barangays, vulnerable groups, critical facilities and possible cascading hazards',true,true,30,'STEP-RECORD'),
('34aaaca7-ac10-5dbf-a3fc-234b01e2a2bf'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,4,'Classify the projected impact and compute the lead time left',true,false,45,'STEP-RECORD'),
('597c0c29-02c6-5e0d-a3c9-b92156d8d26a'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,5,'Decide: monitor, city early action, or request a State of Imminent Disaster; record the basis',true,true,60,'GOV-F09'),
('8e4fbed1-dcff-5b4f-b19e-6f001d3d5ab1'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,6,'Record the PDRA in the platform and brief the CDRRMO Head',true,false,75,'STEP-RECORD'),
('42996283-5f6d-53c0-9fbf-0a4222ecdcdb'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,1,'Record the official forecast: issuer, time issued, validity, areas, expected impact time, and both the lead time from issuance and the time left before impact',true,true,0,'STEP-RECORD'),
('98934062-2853-5d92-9d47-c525404bbfff'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,2,'Attach the PDRA summary: exposure, projected severity, cascading hazards, sector needs, and any IRR Rule II Sec. 4 factors relied on',true,true,10,'GOV-F09'),
('134d8a1a-97d0-5708-acd5-86cf886f23a8'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,3,'Prepare the anticipatory action matrix: actions, owners, resources, funding source and target completion',true,false,null,'STEP-RECORD'),
('6c88c434-a21b-5447-93f8-c65d7a9af3b7'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,4,'Convene the CDRRMC (or its authorized mechanism) to review and endorse the request; record the minutes',true,true,null,'STEP-RECORD'),
('f6482fd3-fe6d-578c-85c2-cde602d14962'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,5,'Send the request to RDRRMC VIII and record the time sent and the acknowledgment (RDRRMC replies within 24 hours)',true,true,null,'GOV-F10'),
('9065c52c-f705-58b5-9bac-6dea3601d243'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,6,'Record the RDRRMC VIII recommendation and its reference',true,true,null,'STEP-RECORD'),
